from fastapi.dependencies.utils import get_typed_annotation
import inspect
from typing import ForwardRef

def evaluate_forwardref(forward_ref, globalns, localns):
    return forward_ref._evaluate(globalns, localns, set())

def test_get_typed_annotation():
    globalns = {}

    # Case 1: annotation is None
    print(f"None: {repr(get_typed_annotation(None, globalns))}")

    # Case 2: annotation is 'None'
    print(f"'None': {repr(get_typed_annotation('None', globalns))}")

    # Case 3: annotation is type(None)
    print(f"type(None): {repr(get_typed_annotation(type(None), globalns))}")

if __name__ == "__main__":
    test_get_typed_annotation()

